package pond

// defaultPool is the default pool used by the package-level functions.
var defaultPool = newPool(0, nil)

// Submit submits a task to the default pool and returns a future that can be used to wait for the task to complete.
func Submit(task func()) Task {
	return defaultPool.Submit(task)
}

// SubmitErr submits a task to the default pool and returns a future that can be used to wait for the task to complete.
func SubmitErr(task func() error) Task {
	return defaultPool.SubmitErr(task)
}

// NewGroup creates a new task group with the default pool.
func NewGroup() TaskGroup {
	return defaultPool.NewGroup()
}

// NewSubpool creates a new subpool with the default pool.
func NewSubpool(maxConcurrency int) Pool {
	return defaultPool.NewSubpool(maxConcurrency)
}

package pond

import (
	"errors"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/alitto/pond/v2/internal/assert"
)

func TestSubmit(t *testing.T) {

	done := make(chan int, 1)
	task := Submit(func() {
		done <- 10
	})

	err := task.Wait()

	assert.Equal(t, nil, err)
	assert.Equal(t, 10, <-done)
}

func TestSubmitWithError(t *testing.T) {

	task := SubmitErr(func() error {
		return errors.New("sample error")
	})

	err := task.Wait()

	assert.Equal(t, "sample error", err.Error())
}

func TestSubmitWithPanic(t *testing.T) {

	task := Submit(func() {
		panic("dummy panic")
	})

	err := task.Wait()

	assert.True(t, errors.Is(err, ErrPanic))
	assert.True(t, strings.HasPrefix(err.Error(), "task panicked: dummy panic"))
}

func TestNewGroup(t *testing.T) {

	group := NewGroup()

	count := 10
	var done atomic.Int32

	for i := 0; i < count; i++ {
		group.SubmitErr(func() error {
			done.Add(1)
			return nil
		})
	}

	err := group.Wait()
	assert.Equal(t, nil, err)
	assert.Equal(t, count, int(done.Load()))
}

func TestNewSubpool(t *testing.T) {

	pool := NewSubpool(10)

	count := 10
	var done atomic.Int32

	for i := 0; i < count; i++ {
		pool.SubmitErr(func() error {
			done.Add(1)
			return nil
		})
	}

	pool.StopAndWait()

	assert.Equal(t, count, int(done.Load()))
}

package pond

// Task represents a task that can be waited on. If the task fails, the error can be retrieved.
type Task interface {

	// Done returns a channel that is closed when the task is complete or has failed.
	Done() <-chan struct{}

	// Wait waits for the task to complete and returns any error that occurred.
	Wait() error
}

// ResultTask represents a task that yields a result. If the task fails, the error can be retrieved.
type ResultTask[R any] interface {

	// Done returns a channel that is closed when the task is complete or has failed.
	Done() <-chan struct{}

	// Wait waits for the task to complete and returns the result and any error that occurred.
	Wait() (R, error)
}

// Result is deprecated. Use ResultTask instead.
// This interface is maintained for backward compatibility.
//
// Deprecated: Use ResultTask instead.
type Result[R any] interface {

	// Done returns a channel that is closed when the task is complete or has failed.
	Done() <-chan struct{}

	// Wait waits for the task to complete and returns the result and any error that occurred.
	Wait() (R, error)
}

package pond

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"

	"github.com/alitto/pond/v2/internal/future"
)

var ErrGroupStopped = errors.New("task group stopped")

// TaskGroup represents a group of tasks that can be executed concurrently.
// The group can be waited on to block until all tasks have completed.
// If any of the tasks return an error, the group will return the first error encountered.
type TaskGroup interface {

	// Submits a task to the group.
	Submit(tasks ...func()) TaskGroup

	// Submits a task to the group that can return an error.
	SubmitErr(tasks ...func() error) TaskGroup

	// Waits for all tasks in the group to complete.
	// If any of the tasks return an error, the group will return the first error encountered.
	// If the context is cancelled, the group will return the context error.
	// If the group is stopped, the group will return ErrGroupStopped.
	// If a task is running when the context is cancelled or the group is stopped, the task will be allowed to complete before returning.
	Wait() error

	// Returns a channel that is closed when all tasks in the group have completed, a task returns an error, or the group is stopped.
	Done() <-chan struct{}

	// Stops the group and cancels all remaining tasks. Running tasks are not interrupted.
	Stop()

	// Returns the context associated with this group.
	// This context will be cancelled when either the parent context is cancelled
	// or any task in the group returns an error, whichever comes first.
	Context() context.Context
}

// ResultTaskGroup represents a group of tasks that can be executed concurrently.
// As opposed to TaskGroup, the tasks in a ResultTaskGroup yield a result.
// The group can be waited on to block until all tasks have completed.
// If any of the tasks return an error, the group will return the first error encountered.
type ResultTaskGroup[O any] interface {

	// Submits a task to the group.
	Submit(tasks ...func() O) ResultTaskGroup[O]

	// Submits a task to the group that can return an error.
	SubmitErr(tasks ...func() (O, error)) ResultTaskGroup[O]

	// Waits for all tasks in the group to complete and returns the results of each task in the order they were submitted.
	// If any of the tasks return an error, the group will return the first error encountered.
	// If the context is cancelled, the group will return the context error.
	// If the group is stopped, the group will return ErrGroupStopped.
	// If a task is running when the context is cancelled or the group is stopped, the task will be allowed to complete before returning.
	Wait() ([]O, error)

	// Returns a channel that is closed when all tasks in the group have completed, a task returns an error, or the group is stopped.
	Done() <-chan struct{}

	// Stops the group and cancels all remaining tasks. Running tasks are not interrupted.
	Stop()
}

type result[O any] struct {
	Output O
	Err    error
}

type abstractTaskGroup[T func() | func() O, E func() error | func() (O, error), O any] struct {
	pool           *pool
	nextIndex      atomic.Int64
	taskWaitGroup  sync.WaitGroup
	future         *future.CompositeFuture[*result[O]]
	futureResolver future.CompositeFutureResolver[*result[O]]
}

func (g *abstractTaskGroup[T, E, O]) Done() <-chan struct{} {
	return g.future.Done(int(g.nextIndex.Load()))
}

func (g *abstractTaskGroup[T, E, O]) Stop() {
	g.future.Cancel(ErrGroupStopped)
}

func (g *abstractTaskGroup[T, E, O]) Context() context.Context {
	return g.future.Context()
}

func (g *abstractTaskGroup[T, E, O]) Submit(tasks ...T) *abstractTaskGroup[T, E, O] {
	for _, task := range tasks {
		g.submit(task)
	}

	return g
}

func (g *abstractTaskGroup[T, E, O]) SubmitErr(tasks ...E) *abstractTaskGroup[T, E, O] {
	for _, task := range tasks {
		g.submit(task)
	}

	return g
}

func (g *abstractTaskGroup[T, E, O]) submit(task any) {
	index := int(g.nextIndex.Add(1) - 1)

	g.taskWaitGroup.Add(1)

	err := g.pool.submit(func() error {
		defer g.taskWaitGroup.Done()

		// Check if the context has been cancelled to prevent running tasks that are not needed
		if err := g.future.Context().Err(); err != nil {
			// Wrap the error with the context canceled error to reflect that the task was canceled.
			err = errors.Join(ErrContextCanceled, err)

			g.futureResolver(index, &result[O]{
				Err: err,
			}, err)

			return err
		}

		// Invoke the task
		output, err := invokeTask[O](task, g.pool.panicRecovery)

		g.futureResolver(index, &result[O]{
			Output: output,
			Err:    err,
		}, err)

		return err
	}, g.pool.nonBlocking)

	if err != nil {
		g.taskWaitGroup.Done()

		g.futureResolver(index, &result[O]{
			Err: err,
		}, err)
	}
}

type taskGroup struct {
	abstractTaskGroup[func(), func() error, struct{}]
}

func (g *taskGroup) Submit(tasks ...func()) TaskGroup {
	g.abstractTaskGroup.Submit(tasks...)
	return g
}

func (g *taskGroup) SubmitErr(tasks ...func() error) TaskGroup {
	g.abstractTaskGroup.SubmitErr(tasks...)
	return g
}

func (g *taskGroup) Wait() error {
	_, err := g.future.Wait(int(g.nextIndex.Load()))
	// This wait group could reach zero before the future is resolved if called in between tasks being submitted and the future being resolved.
	// That's why we wait for the future to be resolved before waiting for the wait group.
	g.taskWaitGroup.Wait()
	return err
}

type resultTaskGroup[O any] struct {
	abstractTaskGroup[func() O, func() (O, error), O]
}

func (g *resultTaskGroup[O]) Submit(tasks ...func() O) ResultTaskGroup[O] {
	g.abstractTaskGroup.Submit(tasks...)
	return g
}

func (g *resultTaskGroup[O]) SubmitErr(tasks ...func() (O, error)) ResultTaskGroup[O] {
	g.abstractTaskGroup.SubmitErr(tasks...)
	return g
}

func (g *resultTaskGroup[O]) Wait() ([]O, error) {
	results, err := g.future.Wait(int(g.nextIndex.Load()))

	// This wait group could reach zero before the future is resolved if called in between tasks being submitted and the future being resolved.
	// That's why we wait for the future to be resolved before waiting for the wait group.
	g.taskWaitGroup.Wait()

	values := make([]O, len(results))

	for i, result := range results {
		if result != nil {
			values[i] = result.Output
		}
	}

	return values, err
}

func newTaskGroup(pool *pool, ctx context.Context) TaskGroup {
	future, futureResolver := future.NewCompositeFuture[*result[struct{}]](ctx)

	return &taskGroup{
		abstractTaskGroup: abstractTaskGroup[func(), func() error, struct{}]{
			pool:           pool,
			future:         future,
			futureResolver: futureResolver,
		},
	}
}

func newResultTaskGroup[O any](pool *pool, ctx context.Context) ResultTaskGroup[O] {
	future, futureResolver := future.NewCompositeFuture[*result[O]](ctx)

	return &resultTaskGroup[O]{
		abstractTaskGroup: abstractTaskGroup[func() O, func() (O, error), O]{
			pool:           pool,
			future:         future,
			futureResolver: futureResolver,
		},
	}
}

package pond

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/alitto/pond/v2/internal/assert"
)

func TestResultTaskGroupWait(t *testing.T) {

	pool := NewResultPool[int](10)

	group := pool.NewGroup()

	for i := 0; i < 5; i++ {
		i := i
		group.Submit(func() int {
			return i
		})
	}

	outputs, err := group.Wait()

	assert.Equal(t, nil, err)
	assert.Equal(t, 5, len(outputs))
	assert.Equal(t, 0, outputs[0])
	assert.Equal(t, 1, outputs[1])
	assert.Equal(t, 2, outputs[2])
	assert.Equal(t, 3, outputs[3])
	assert.Equal(t, 4, outputs[4])
}

func TestResultTaskGroupWaitWithError(t *testing.T) {

	pool := NewResultPool[int](1)

	group := pool.NewGroup()

	sampleErr := errors.New("sample error")

	for i := 0; i < 5; i++ {
		i := i
		if i == 3 {
			group.SubmitErr(func() (int, error) {
				return 0, sampleErr
			})
		} else {
			group.SubmitErr(func() (int, error) {
				return i, nil
			})
		}
	}

	outputs, err := group.Wait()

	assert.Equal(t, sampleErr, err)
	assert.Equal(t, 5, len(outputs))
	assert.Equal(t, 0, outputs[0])
	assert.Equal(t, 1, outputs[1])
	assert.Equal(t, 2, outputs[2])
	assert.Equal(t, 0, outputs[3]) // This task returned an error
	assert.Equal(t, 0, outputs[4]) // This task was not executed
}

func TestResultTaskGroupWaitWithErrorInLastTask(t *testing.T) {

	group := NewResultPool[int](10).
		NewGroup()

	sampleErr := errors.New("sample error")

	group.SubmitErr(func() (int, error) {
		return 1, nil
	})

	time.Sleep(10 * time.Millisecond)

	group.SubmitErr(func() (int, error) {
		return 0, sampleErr
	})

	outputs, err := group.Wait()

	assert.Equal(t, sampleErr, err)
	assert.Equal(t, 2, len(outputs))
	assert.Equal(t, 1, outputs[0])
	assert.Equal(t, 0, outputs[1])
}

func TestResultTaskGroupWaitWithMultipleErrors(t *testing.T) {

	pool := NewResultPool[int](10)

	group := pool.NewGroup()

	sampleErr := errors.New("sample error")

	wg := sync.WaitGroup{}
	wg.Add(5)

	for i := 0; i < 5; i++ {
		i := i
		group.SubmitErr(func() (int, error) {
			wg.Done()
			wg.Wait() // Wait until all tasks have started

			if i%2 == 0 {
				time.Sleep(10 * time.Millisecond)
				return 0, sampleErr
			}
			return i, nil
		})
	}

	outputs, err := group.Wait()

	assert.Equal(t, sampleErr, err)
	assert.Equal(t, 5, len(outputs))
	assert.Equal(t, 0, outputs[0])
	assert.Equal(t, 1, outputs[1])
	assert.Equal(t, 0, outputs[2])
	assert.Equal(t, 3, outputs[3])
	assert.Equal(t, 0, outputs[4])
}

func TestResultTaskGroupWaitWithContextCanceledAndOngoingTasks(t *testing.T) {
	pool := NewResultPool[string](1)

	ctx, cancel := context.WithCancel(context.Background())

	group := pool.NewGroupContext(ctx)

	group.Submit(func() string {
		cancel() // cancel the context after the first task is started
		time.Sleep(10 * time.Millisecond)
		return "output1"
	})

	group.Submit(func() string {
		time.Sleep(10 * time.Millisecond)
		return "output2"
	})

	results, err := group.Wait()

	assert.Equal(t, context.Canceled, err)
	assert.Equal(t, int(2), len(results))
	assert.Equal(t, "", results[0])
	assert.Equal(t, "", results[1])
}

func TestTaskGroupWaitWithContextCanceledAndOngoingTasks(t *testing.T) {
	pool := NewPool(1)

	var executedCount atomic.Int32

	ctx, cancel := context.WithCancel(context.Background())

	group := pool.NewGroupContext(ctx)

	group.Submit(func() {
		cancel() // cancel the context after the first task is started
		time.Sleep(10 * time.Millisecond)
		executedCount.Add(1)
	})

	group.Submit(func() {
		time.Sleep(10 * time.Millisecond)
		executedCount.Add(1)
	})

	err := group.Wait()

	assert.Equal(t, context.Canceled, err)
	assert.Equal(t, int32(1), executedCount.Load())
}

func TestTaskGroupWaitShouldNotDeadlockWhenPoolContextCanceledWithQueuedTasks(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	pool := NewPool(1, WithContext(ctx))
	group := pool.NewGroup()

	firstTaskStarted := make(chan struct{})
	releaseFirstTask := make(chan struct{})

	group.Submit(func() {
		close(firstTaskStarted)
		<-releaseFirstTask
	})

	// This task stays queued while the only worker is blocked in the first task.
	group.Submit(func() {})

	<-firstTaskStarted
	cancel()
	close(releaseFirstTask)

	waitDone := make(chan error, 1)
	go func() {
		waitDone <- group.Wait()
	}()

	select {
	case err := <-waitDone:
		assert.Equal(t, context.Canceled, err)
	case <-time.After(250 * time.Millisecond):
		t.Fatal("group.Wait blocked after pool context cancellation with queued tasks")
	}

	assert.Equal(t, uint64(2), pool.SubmittedTasks())
	assert.Equal(t, uint64(1), pool.CompletedTasks())
	assert.Equal(t, uint64(1), pool.SuccessfulTasks())
	assert.Equal(t, uint64(0), pool.FailedTasks())
	assert.Equal(t, uint64(1), pool.CanceledTasks())
	assert.Equal(t, uint64(0), pool.DroppedTasks())
	assert.Equal(t, uint64(0), pool.WaitingTasks())
	assert.Equal(t, int64(0), pool.RunningWorkers())
}

func TestTaskGroupWithStoppedPool(t *testing.T) {

	pool := NewPool(100)

	pool.StopAndWait()

	err := pool.NewGroup().Submit(func() {}).Wait()

	assert.Equal(t, ErrPoolStopped, err)
}

func TestTaskGroupWithContextCanceled(t *testing.T) {

	pool := NewPool(100)

	group := pool.NewGroup()

	ctx, cancel := context.WithCancel(context.Background())

	taskStarted := make(chan struct{})

	task := group.SubmitErr(func() error {
		taskStarted <- struct{}{}

		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(100 * time.Millisecond):
			return nil
		}
	})

	<-taskStarted
	cancel()

	err := task.Wait()

	assert.Equal(t, context.Canceled, err)
}

func TestTaskGroupWithNoTasks(t *testing.T) {

	group := NewResultPool[int](10).
		NewGroup()

	results, err := group.Submit().Wait()

	assert.Equal(t, nil, err)
	assert.Equal(t, 0, len(results))

	results, err = group.SubmitErr().Wait()

	assert.Equal(t, nil, err)
	assert.Equal(t, 0, len(results))
}

func TestTaskGroupCanceledShouldSkipRemainingTasks(t *testing.T) {

	pool := NewPool(1)

	group := pool.NewGroup()

	var executedCount atomic.Int32
	sampleErr := errors.New("sample error")

	group.Submit(func() {
		executedCount.Add(1)
	})

	group.SubmitErr(func() error {
		time.Sleep(10 * time.Millisecond)
		return sampleErr
	})

	group.Submit(func() {
		executedCount.Add(1)
	})

	err := group.Wait()

	assert.Equal(t, sampleErr, err)
	assert.Equal(t, int32(1), executedCount.Load())
}

func TestTaskGroupWithCustomContext(t *testing.T) {
	pool := NewPool(1)

	ctx, cancel := context.WithCancel(context.Background())

	group := pool.NewGroupContext(ctx)

	var executedCount atomic.Int32

	group.Submit(func() {
		executedCount.Add(1)
	})
	group.Submit(func() {
		executedCount.Add(1)
		cancel()
	})
	group.Submit(func() {
		executedCount.Add(1)
	})

	err := group.Wait()

	assert.Equal(t, context.Canceled, err)
	assert.Equal(t, struct{}{}, <-group.Done())
	assert.Equal(t, int32(2), executedCount.Load())
}

func TestTaskGroupStop(t *testing.T) {
	pool := NewPool(1)

	group := pool.NewGroup()

	var executedCount atomic.Int32

	group.Submit(func() {
		executedCount.Add(1)
	})
	group.Submit(func() {
		executedCount.Add(1)
		group.Stop()
	})
	group.Submit(func() {
		executedCount.Add(1)
	})

	err := group.Wait()

	assert.Equal(t, ErrGroupStopped, err)
	assert.Equal(t, struct{}{}, <-group.Done())
	assert.Equal(t, int32(2), executedCount.Load())
}

func TestTaskGroupDone(t *testing.T) {
	pool := NewPool(10)

	group := pool.NewGroup()

	var executedCount atomic.Int32

	for i := 0; i < 5; i++ {
		group.Submit(func() {
			time.Sleep(1 * time.Millisecond)
			executedCount.Add(1)
		})
	}

	<-group.Done()

	assert.Equal(t, int32(5), executedCount.Load())
}

func TestTaskGroupMetrics(t *testing.T) {
	pool := NewPool(1)

	group := pool.NewGroup()

	for i := 0; i < 9; i++ {
		group.Submit(func() {
			time.Sleep(1 * time.Millisecond)
		})
	}

	// The last task will return an error
	sampleErr := errors.New("sample error")
	group.SubmitErr(func() error {
		time.Sleep(1 * time.Millisecond)
		return sampleErr
	})

	err := group.Wait()

	time.Sleep(10 * time.Millisecond)

	assert.Equal(t, sampleErr, err)
	assert.Equal(t, uint64(10), pool.SubmittedTasks())
	assert.Equal(t, uint64(9), pool.SuccessfulTasks())
	assert.Equal(t, uint64(1), pool.FailedTasks())
}

func TestTaskGroupMetricsWithCancelledContext(t *testing.T) {
	pool := NewPool(1)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	group := pool.NewGroupContext(ctx)

	for i := 0; i < 10; i++ {
		i := i
		group.Submit(func() {
			time.Sleep(20 * time.Millisecond)
			if i == 4 {
				cancel()
			}
		})
	}
	err := group.Wait()

	time.Sleep(10 * time.Millisecond)

	assert.Equal(t, err, context.Canceled)
	assert.Equal(t, uint64(10), pool.SubmittedTasks())
	assert.Equal(t, uint64(5), pool.SuccessfulTasks())
	assert.Equal(t, uint64(0), pool.FailedTasks())
	assert.Equal(t, uint64(5), pool.CanceledTasks())
}

func TestTaskGroupWaitingTasks(t *testing.T) {
	// Create a pool with limited concurrency
	pool := NewPool(10)

	// Create a task group
	group := pool.NewGroup()

	start := make(chan struct{})
	end := make(chan struct{})

	// Submit 20 tasks
	for i := 0; i < 20; i++ {
		group.Submit(func() {
			<-start
			<-end
		})
	}

	// Start half of the tasks
	for i := 0; i < 10; i++ {
		start <- struct{}{}
	}

	assert.Equal(t, int64(10), pool.RunningWorkers())
	assert.Equal(t, uint64(10), pool.WaitingTasks())

	// Wait for all tasks to complete
	close(start)
	close(end)
	group.Wait()
}

func TestTaskGroupContext(t *testing.T) {
	pool := NewPool(2)

	group := pool.NewGroupContext(context.Background())

	tasksRunning := sync.WaitGroup{}
	tasksRunning.Add(2)

	group.SubmitErr(func() error {
		// Wait for all tasks to be running
		tasksRunning.Done()
		tasksRunning.Wait()

		return errors.New("first task error")
	})

	group.SubmitErr(func() error {
		// Wait for all tasks to be running
		tasksRunning.Done()
		tasksRunning.Wait()

		select {
		case <-group.Context().Done():
			return errors.New("second task canceled")
		case <-time.After(100 * time.Millisecond):
			return nil
		}
	})

	group.Submit(func() {})

	err := group.Wait()

	pool.StopAndWait()

	assert.Equal(t, "first task error", err.Error())
	assert.Equal(t, struct{}{}, <-group.Done())
	assert.Equal(t, struct{}{}, <-group.Context().Done())
	assert.Equal(t, uint64(3), pool.SubmittedTasks())
	assert.Equal(t, uint64(0), pool.SuccessfulTasks())
	assert.Equal(t, uint64(2), pool.FailedTasks())
	assert.Equal(t, uint64(1), pool.CanceledTasks())
}

package assert

import "testing"

/**
 * Asserts that the expected and actual values are equal.
 */
func Equal(t *testing.T, expected interface{}, actual interface{}) {
	if expected != actual {
		t.Helper()
		t.Errorf("Expected %T(%v) but was %T(%v)", expected, expected, actual, actual)
	}
}

/**
 * Asserts that the actual value is true.
 */
func True(t *testing.T, actual bool) {
	if !actual {
		t.Helper()
		t.Errorf("Expected true but was %T(%v)", actual, actual)
	}
}

/**
 * Asserts that the function panics with the expected object.
 */
func PanicsWith(t *testing.T, expected any, f func()) {
	defer func() {
		if r := recover(); r != nil {
			Equal(t, expected, r)
		} else {
			t.Errorf("Expected a panic, but got nil")
		}
	}()
	f()
}

/**
 * Asserts that the function panics with the expected error.
 */
func PanicsWithError(t *testing.T, expected string, f func()) {
	defer func() {
		if r := recover(); r != nil {
			err, ok := r.(error)
			if !ok {
				t.Errorf("Expected a panic with error, but got %T(%v)", r, r)
				return
			}
			Equal(t, expected, err.Error())
		} else {
			t.Errorf("Expected a panic, but got nil")
		}
	}()
	f()
}

/**
 * Asserts that the function not panics.
 */
func NotPanics(t *testing.T, f func()) {
	defer func() {
		if r := recover(); r != nil {
			t.Errorf("No panic was expected, but got %T(%v)", r, r)
		}
	}()
	f()
}

package future

import (
	"context"
	"fmt"
	"sync"
)

type CompositeFutureResolver[V any] func(index int, value V, err error)

type compositeResolution[V any] struct {
	index int
	value V
}

type compositeErrorResolution struct {
	index int
	err   error
}

func (e *compositeErrorResolution) Error() string {
	return e.err.Error()
}

type waitListener struct {
	count int
	ch    chan struct{}
}

type CompositeFuture[V any] struct {
	ctx         context.Context
	cancel      context.CancelCauseFunc
	resolutions []compositeResolution[V]
	mutex       sync.Mutex
	listeners   []waitListener
}

func NewCompositeFuture[V any](ctx context.Context) (*CompositeFuture[V], CompositeFutureResolver[V]) {
	childCtx, cancel := context.WithCancelCause(ctx)

	future := &CompositeFuture[V]{
		ctx:         childCtx,
		cancel:      cancel,
		resolutions: make([]compositeResolution[V], 0),
	}

	return future, future.resolve
}

func (f *CompositeFuture[V]) Done(count int) <-chan struct{} {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	ch := make(chan struct{})

	err := context.Cause(f.ctx)

	// Return immediately if the context is already canceled or the count is already reached
	if len(f.resolutions) >= count || err != nil {
		close(ch)
		return ch
	}

	// Register a listener
	f.listeners = append(f.listeners, waitListener{
		count: count,
		ch:    ch,
	})

	return ch
}

func (f *CompositeFuture[V]) Context() context.Context {
	return f.ctx
}

func (f *CompositeFuture[V]) Cancel(cause error) {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	// Cancel the context
	f.cancel(cause)

	// Notify listeners
	f.notifyListeners()
}

func (f *CompositeFuture[V]) Wait(count int) ([]V, error) {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	result, err := f.getResult(count)
	if result != nil || err != nil {
		return result, err
	}

	// Register a listener
	ch := make(chan struct{})
	f.listeners = append(f.listeners, waitListener{
		count: count,
		ch:    ch,
	})

	f.mutex.Unlock()

	// Wait for the listener to be notified or the context to be canceled
	select {
	case <-ch:
	case <-f.ctx.Done():
	}

	f.mutex.Lock()

	return f.getResult(count)
}

func (f *CompositeFuture[V]) resolve(index int, value V, err error) {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	if index < 0 {
		panic(fmt.Errorf("index must be greater than or equal to 0"))
	}

	// Cancel the context if an error occurred
	if err != nil {
		f.cancel(&compositeErrorResolution{
			index: index,
			err:   err,
		})
	} else if context.Cause(f.ctx) == nil {
		// Save the resolution
		f.resolutions = append(f.resolutions, compositeResolution[V]{
			index: index,
			value: value,
		})
	}

	// Notify listeners
	f.notifyListeners()
}

func (f *CompositeFuture[V]) getResult(count int) (values []V, err error) {

	cause := context.Cause(f.ctx)

	// If we have enough results, return them
	if cause != nil || len(f.resolutions) >= count {
		// Get sorted resolution values
		values = make([]V, count)
		for _, resolution := range f.resolutions {
			if resolution.index < count {
				values[resolution.index] = resolution.value
			}
		}
	}

	if cause == nil {
		return
	}

	if errorResolution, ok := cause.(*compositeErrorResolution); ok {
		// Unwrap the error resolution
		err = errorResolution.err
	} else if len(f.resolutions) < count {
		// If the context is canceled and we have collected enough results, return nil error
		// because we assume that context cancellation happened after the last resolution.
		err = cause
	}

	return
}

func (f *CompositeFuture[V]) notifyListeners() {

	err := context.Cause(f.ctx)

	// Notify listeners
	for i := 0; i < len(f.listeners); i++ {
		listener := f.listeners[i]

		if err != nil || listener.count <= len(f.resolutions) {
			close(listener.ch)
			f.listeners = append(f.listeners[:i], f.listeners[i+1:]...)
			i--
		}
	}
}

