	ctx := context.Background()

	future, resolve := NewFuture(ctx)

	sampleErr := errors.New("sample error")

	resolve(sampleErr)

	err := future.Wait()

	assert.Equal(t, sampleErr, err)
	assert.Equal(t, "sample error", err.Error())
	assert.Equal(t, sampleErr, future.Err())
}

