func TestPoolWithQueueSizeZero(t *testing.T) {

	pool := NewPool(1, WithQueueSize(0))

	assert.Equal(t, 0, pool.QueueSize())

	firstStarted := make(chan struct{})
	releaseFirst := make(chan struct{})

	firstTask := pool.Submit(func() {
		firstStarted <- struct{}{}
		<-releaseFirst
	})

	<-firstStarted

	secondTaskCh := make(chan Task, 1)
	secondRan := make(chan struct{}, 1)

	go func() {
		task := pool.Submit(func() {
			secondRan <- struct{}{}
		})
		secondTaskCh <- task
	}()

	time.Sleep(10 * time.Millisecond)

	assert.Equal(t, uint64(0), pool.WaitingTasks())

	select {
	case <-secondTaskCh:
		t.Fatalf("expected submit to block when queue size is zero and worker is busy")
	default:
	}

	droppedTask, ok := pool.TrySubmit(func() {})
	assert.True(t, !ok)
	assert.Equal(t, ErrQueueFull, droppedTask.Wait())
	assert.Equal(t, uint64(1), pool.DroppedTasks())

	close(releaseFirst)

	secondTask := <-secondTaskCh
	assert.Equal(t, nil, secondTask.Wait())

	select {
	case <-secondRan:
	case <-time.After(50 * time.Millisecond):
		t.Fatalf("second task was not executed after releasing the first")
	}

	assert.Equal(t, nil, firstTask.Wait())
	assert.Equal(t, uint64(0), pool.WaitingTasks())
	assert.Equal(t, uint64(3), pool.SubmittedTasks())
	assert.Equal(t, uint64(2), pool.CompletedTasks())
	assert.Equal(t, uint64(2), pool.SuccessfulTasks())
	assert.Equal(t, uint64(0), pool.FailedTasks())

	pool.Stop().Wait()
}

func TestPoolResize(t *testing.T) {

	pool := NewPool(1, WithQueueSize(10))

	assert.Equal(t, 1, pool.MaxConcurrency())

	waitForMetrics := func(waitingTasks uint64, runningWorkers int64) {
		t.Helper()

		deadline := time.Now().Add(2 * time.Second)
		for {
			currentWaitingTasks := pool.WaitingTasks()
			currentRunningWorkers := pool.RunningWorkers()
			if currentWaitingTasks == waitingTasks && currentRunningWorkers == runningWorkers {
				return
			}

			if time.Now().After(deadline) {
				t.Fatalf(
					"timed out waiting for metrics: expected waiting=%d running=%d, got waiting=%d running=%d",
					waitingTasks,
					runningWorkers,
					currentWaitingTasks,
					currentRunningWorkers,
				)
			}

			time.Sleep(1 * time.Millisecond)
		}
	}

	taskStarted := make(chan struct{}, 10)
	taskWait := make(chan struct{}, 10)

	// Submit 10 tasks
	for i := 0; i < 10; i++ {
		pool.Submit(func() {
			<-taskStarted
			<-taskWait
		})
	}

	// Unblock 3 tasks
	for i := 0; i < 3; i++ {
		taskStarted <- struct{}{}
	}

	// Verify only 1 task is running and 9 are waiting
	waitForMetrics(uint64(9), int64(1))

	// Increase max concurrency to 3
	pool.Resize(3)
	assert.Equal(t, 3, pool.MaxConcurrency())

	// Unblock 3 more tasks
	for i := 0; i < 3; i++ {
		taskStarted <- struct{}{}
	}

	// Verify 3 tasks are running and 7 are waiting
	waitForMetrics(uint64(7), int64(3))

	// Decrease max concurrency to 2
	pool.Resize(2)
	assert.Equal(t, 2, pool.MaxConcurrency())

	// Complete the 3 running tasks
	for i := 0; i < 3; i++ {
		taskWait <- struct{}{}
	}

	// Unblock all remaining tasks
	for i := 0; i < 4; i++ {
		taskStarted <- struct{}{}
	}

	// Ensure 2 tasks are running and 5 are waiting
	waitForMetrics(uint64(5), int64(2))

	close(taskWait)

	pool.Stop().Wait()
}

func TestPoolResizeBeforeWorkersRetire(t *testing.T) {
	for _, subpool := range []bool{false, true} {
		for _, test := range []struct {
			name          string
			retired       int
			maxWorkers    int
			running       int64
			startedQueued int
		}{
			{name: "still_above_limit", maxWorkers: 3, running: 5},
			{name: "partially_retired", retired: 2, maxWorkers: 4, running: 4, startedQueued: 1},
			{name: "grow_above_original_limit", maxWorkers: 7, running: 7, startedQueued: 2},
		} {
			name := test.name
			if subpool {
				name = "subpool/" + name
			}
			t.Run(name, func(t *testing.T) {
				var parent, pool Pool
				if subpool {
					parent = NewPool(10)
					pool = parent.NewSubpool(5)
				} else {
					pool = NewPool(5)
				}

				started := make(chan struct{}, 5)
				queuedStarted := make(chan struct{}, 2)
				releaseQueued := make(chan struct{})
				releases := make([]chan struct{}, 5)
				for i := range releases {
					releases[i] = make(chan struct{})
				}
				released := 0
				t.Cleanup(func() {
					for _, release := range releases[released:] {
						close(release)
					}
					close(releaseQueued)
					pool.StopAndWait()
					if parent != nil {
						parent.StopAndWait()
					}
				})

				for _, release := range releases {
					release := release
					pool.Submit(func() {
						started <- struct{}{}
						<-release
					})
				}
				for range releases {
					select {
					case <-started:
					case <-time.After(2 * time.Second):
						t.Fatal("timed out waiting for initial workers")
					}
				}
				for i := 0; i < 2; i++ {
					pool.Submit(func() {
						queuedStarted <- struct{}{}
						<-releaseQueued
					})
				}

				pool.Resize(1)
				for _, release := range releases[:test.retired] {
					close(release)
					released++
				}
				deadline := time.Now().Add(2 * time.Second)
				for pool.RunningWorkers() != int64(5-test.retired) {
					if time.Now().After(deadline) {
						t.Fatal("timed out waiting for workers to retire")
					}
					time.Sleep(time.Millisecond)
				}

				pool.Resize(test.maxWorkers)
				assert.Equal(t, test.maxWorkers, pool.MaxConcurrency())
				assert.Equal(t, test.running, pool.RunningWorkers())
				for i := 0; i < test.startedQueued; i++ {
					select {
					case <-queuedStarted:
					case <-time.After(2 * time.Second):
						t.Fatal("timed out waiting for queued tasks")
					}
				}
				assert.Equal(t, test.startedQueued, 2-int(pool.WaitingTasks()))
				if parent != nil {
					assert.Equal(t, uint64(5+2*test.startedQueued), parent.SubmittedTasks())
				}
			})
		}
	}
}

func TestSubpoolResizeBeforeWorkersRetireWithFullParent(t *testing.T) {
	parent := NewPool(5, WithQueueSize(0))
	pool := parent.NewSubpool(5, WithQueueSize(2))
	started := make(chan struct{}, 5)
	release := make(chan struct{})
	resized := make(chan struct{})
	t.Cleanup(func() {
		close(release)
		<-resized
		pool.StopAndWait()
		parent.StopAndWait()
	})

	for i := 0; i < 5; i++ {
		pool.Submit(func() {
			started <- struct{}{}
			<-release
		})
	}
	for i := 0; i < 5; i++ {
		<-started
	}
	pool.Submit(func() {})
	pool.Submit(func() {})
	pool.Resize(1)
	go func() {
		pool.Resize(3)
		close(resized)
	}()

	select {
	case <-resized:
	case <-time.After(2 * time.Second):
		t.Fatal("resize blocked on the full parent while existing workers exceed the new limit")
	}
}

