// TestStopAndWaitWithGoexit reproduces issue #135: StopAndWait() blocks indefinitely
// when runtime.Goexit() is called inside a task. This commonly occurs with gomock
// in unit tests, which uses runtime.Goexit() when expectations fail.
func TestStopAndWaitWithGoexit(t *testing.T) {
	pool := NewPool(10)

	pool.SubmitErr(func() error {
		runtime.Goexit()
		return nil
	})

	done := make(chan struct{})
	go func() {
		pool.StopAndWait()
		close(done)
	}()

	select {
	case <-done:
		// StopAndWait completed - bug is fixed
	case <-time.After(2 * time.Second):
		t.Fatal("StopAndWait() blocked indefinitely")
	}
}

// TestTaskInvokesGoexitAndRecover
func TestTaskInvokesGoexitAndPoolRecovers(t *testing.T) {
	pool := NewPool(1)

	// Submit a task that will invoke runtime.Goexit() and kill the worker
	taskGoexit := pool.SubmitErr(func() error {
		runtime.Goexit()
		return nil
	})

	// Submit another task that should execute normally after the first task is killed
	taskNormal := pool.SubmitErr(func() error {
		return nil
	})

	done := make(chan struct{})
	go func() {
		pool.StopAndWait()
		close(done)
	}()

	select {
	case <-done:
		// StopAndWait completed
		assert.Equal(t, ErrPoolStopped, taskGoexit.Wait())
		assert.Equal(t, nil, taskNormal.Wait())

		assert.Equal(t, int64(0), pool.RunningWorkers())
		assert.Equal(t, uint64(2), pool.SubmittedTasks())
		assert.Equal(t, uint64(2), pool.CompletedTasks())
		assert.Equal(t, uint64(1), pool.SuccessfulTasks())
		assert.Equal(t, uint64(1), pool.FailedTasks())
		assert.Equal(t, uint64(0), pool.DroppedTasks())
	case <-time.After(2 * time.Second):
		t.Fatal("StopAndWait() blocked indefinitely")
	}
}

package pond

import (
	"context"
)

type Option func(*pool)

// WithContext sets the context for the pool.
func WithContext(ctx context.Context) Option {
	return func(p *pool) {
		p.ctx = ctx
	}
}

// WithQueueSize sets the max number of elements that can be queued in the pool.
func WithQueueSize(size int) Option {
	return func(p *pool) {
		p.queueSize = size
	}
}

// WithNonBlocking sets the pool to be non-blocking when the queue is full.
// This option is only effective when the queue size is set.
func WithNonBlocking(nonBlocking bool) Option {
	return func(p *pool) {
		p.nonBlocking = nonBlocking
	}
}

// WithoutPanicRecovery disables panic interception inside worker goroutines.
// When this option is enabled, panics inside tasks will propagate just like regular goroutines.
func WithoutPanicRecovery() Option {
	return func(p *pool) {
		p.panicRecovery = false
	}
}

package pond

import (
	"context"

	"github.com/alitto/pond/v2/internal/future"
)

// ResultPool is a pool that can be used to submit tasks that return a result.
type ResultPool[R any] interface {
	BasePool

	// Submits a task to the pool and returns a future that can be used to wait for the task to complete and get the result.
	// The pool will not accept new tasks after it has been stopped.
	// If the pool has been stopped, this method will return ErrPoolStopped.
	Submit(task func() R) ResultTask[R]

	// Submits a task to the pool and returns a future that can be used to wait for the task to complete and get the result.
	// The task function must return a result and an error.
	// The pool will not accept new tasks after it has been stopped.
	// If the pool has been stopped, this method will return ErrPoolStopped.
	SubmitErr(task func() (R, error)) ResultTask[R]

	// Attempts to submit a task to the pool and returns a future that can be used to wait for the task to complete
	// and a boolean indicating whether the task was submitted successfully.
	// The pool will not accept new tasks after it has been stopped.
	// If the pool has been stopped, this method will return ErrPoolStopped.
	TrySubmit(task func() R) (ResultTask[R], bool)

	// Attempts to submit a task to the pool and returns a future that can be used to wait for the task to complete
	// and a boolean indicating whether the task was submitted successfully.
	// The task function must return a result and an error.
	// The pool will not accept new tasks after it has been stopped.
	// If the pool has been stopped, this method will return ErrPoolStopped.
	TrySubmitErr(task func() (R, error)) (ResultTask[R], bool)

	// Creates a new subpool with the specified maximum concurrency and options.
	NewSubpool(maxConcurrency int, options ...Option) ResultPool[R]

	// Creates a new task group.
	NewGroup() ResultTaskGroup[R]

	// Creates a new task group with the specified context.
	NewGroupContext(ctx context.Context) ResultTaskGroup[R]
}

type resultPool[R any] struct {
	*pool
}

func (p *resultPool[R]) NewGroup() ResultTaskGroup[R] {
	return newResultTaskGroup[R](p.pool, p.Context())
}

func (p *resultPool[R]) NewGroupContext(ctx context.Context) ResultTaskGroup[R] {
	return newResultTaskGroup[R](p.pool, ctx)
}

func (p *resultPool[R]) Submit(task func() R) ResultTask[R] {
	future, _ := p.submit(task, p.nonBlocking)
	return future
}

func (p *resultPool[R]) SubmitErr(task func() (R, error)) ResultTask[R] {
	future, _ := p.submit(task, p.nonBlocking)
	return future
}

func (p *resultPool[R]) TrySubmit(task func() R) (ResultTask[R], bool) {
	return p.submit(task, true)
}

func (p *resultPool[R]) TrySubmitErr(task func() (R, error)) (ResultTask[R], bool) {
	return p.submit(task, true)
}

func (p *resultPool[R]) submit(task any, nonBlocking bool) (ResultTask[R], bool) {
	ctx := p.Context()
	future, resolve := future.NewValueFuture[R](ctx)

	if p.Stopped() {
		var zero R
		resolve(zero, ErrPoolStopped)
		return future, false
	}

	wrapped := wrapTask[R, func(R, error)](task, resolve, ctx, p.pool.panicRecovery)

	if err := p.pool.submit(wrapped, nonBlocking); err != nil {
		var zero R
		resolve(zero, err)
		return future, false
	}

	return future, true
}

func (p *resultPool[R]) NewSubpool(maxConcurrency int, options ...Option) ResultPool[R] {
	return newResultPool[R](maxConcurrency, p.pool, options...)
}

func newResultPool[R any](maxConcurrency int, parent *pool, options ...Option) *resultPool[R] {
	return &resultPool[R]{
		pool: newPool(maxConcurrency, parent, options...),
	}
}

// NewResultPool creates a new result pool with the given maximum concurrency and options.
// Result pools are generic pools that can be used to submit tasks that return a result.
// The new maximum concurrency must be greater than or equal to 0 (0 means no limit).
func NewResultPool[R any](maxConcurrency int, options ...Option) ResultPool[R] {
	return newResultPool[R](maxConcurrency, nil, options...)
}

